INSERT INTO curriculum_revised(payload) VALUES ($guide_payload$[{"slug":"talora-business-analysis-2026","task_number":1,"title":"Business Problem Discovery","old_instructions":"[[AZ]]\n## Məqsəd\nProblemi bir cümlə ilə müəyyən et ;  Üç maraqlı tərəfin ehtiyaclarını müqayisə et ;  Problemi fakt və fərziyyələrə ayır.\n\n## Addım-addım icra\n1. Problemi bir cümlə ilə müəyyən et.\n2. Üç maraqlı tərəfin ehtiyaclarını müqayisə et.\n3. Problemi fakt və fərziyyələrə ayır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nProblem statement və fərziyyə cədvəli. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDefine the problem in one sentence ;  Compare needs of three stakeholders ;  Separate facts from assumptions.\n\n## Step-by-step\n1. Define the problem in one sentence.\n2. Compare needs of three stakeholders.\n3. Separate facts from assumptions.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nProblem statement and assumption table. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nProblemi bir cümlə ilə müəyyən et ;  Üç maraqlı tərəfin ehtiyaclarını müqayisə et ;  Problemi fakt və fərziyyələrə ayır.\n\n[[EN]]\nDefine the problem in one sentence ;  Compare needs of three stakeholders ;  Separate facts from assumptions.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Business Problem Discovery\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Nəticə biznes problemini və ölçülə bilən qərarı izah etməlidir.\n**Nümunə situasiya:** Müraciət cavabının gecikməsini (məsələn, 48 saat) problem kimi təsvir et; tələbə, admin və universitetin ehtiyaclarını ayır.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Business Analysis / Task-1. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Problemi bir cümlə ilə müəyyən et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Üç maraqlı tərəfin ehtiyaclarını müqayisə et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Problemi fakt və fərziyyələrə ayır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Müraciət cavabının gecikməsini (məsələn, 48 saat) problem kimi təsvir et; tələbə, admin və universitetin ehtiyaclarını ayır. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Problem statement və fərziyyə cədvəli. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nMüraciət cavabının gecikməsini (məsələn, 48 saat) problem kimi təsvir et; tələbə, admin və universitetin ehtiyaclarını ayır.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Problem statement və fərziyyə cədvəli.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Fakt və fərziyyələri ayır, kimin qərar verəcəyini göstər.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Business Problem Discovery\nThis practical assignment is designed for beginners. Connect the artifact to a measurable business decision.\n**Example scenario:** Describe a 48-hour application response delay and distinguish student, admin and university needs.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Business Analysis / Task-1. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Define the problem in one sentence. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Compare needs of three stakeholders. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Separate facts from assumptions. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Describe a 48-hour application response delay and distinguish student, admin and university needs. Document what worked and any limitations.\n7. Complete the main artifact: Problem statement and assumption table. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nDescribe a 48-hour application response delay and distinguish student, admin and university needs.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Problem statement and assumption table.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Distinguish facts from assumptions and identify the decision owner.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nBusiness Problem Discovery: Problemi bir cümlə ilə müəyyən et. Üç maraqlı tərəfin ehtiyaclarını müqayisə et. Problemi fakt və fərziyyələrə ayır. Pulsuz alətlər: Google Docs, Google Sheets. Nəticə: Problem statement və fərziyyə cədvəli.\n\n[[EN]]\nBusiness Problem Discovery: Define the problem in one sentence. Compare needs of three stakeholders. Separate facts from assumptions. Free tools: Google Docs, Google Sheets. Output: Problem statement and assumption table."},{"slug":"talora-business-analysis-2026","task_number":2,"title":"Stakeholder Mapping","old_instructions":"[[AZ]]\n## Məqsəd\nTəsirlənən beş rol müəyyən et ;  Influence-interest matrisi qur ;  Hər rol üçün müsahibə sualları hazırla.\n\n## Addım-addım icra\n1. Təsirlənən beş rol müəyyən et.\n2. Influence-interest matrisi qur.\n3. Hər rol üçün müsahibə sualları hazırla.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nStakeholder matrix və sual siyahısı. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nIdentify five impacted roles ;  Create an influence-interest matrix ;  Draft interview questions for each role.\n\n## Step-by-step\n1. Identify five impacted roles.\n2. Create an influence-interest matrix.\n3. Draft interview questions for each role.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nStakeholder matrix and interview guide. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nTəsirlənən beş rol müəyyən et ;  Influence-interest matrisi qur ;  Hər rol üçün müsahibə sualları hazırla.\n\n[[EN]]\nIdentify five impacted roles ;  Create an influence-interest matrix ;  Draft interview questions for each role.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Stakeholder Mapping\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Nəticə biznes problemini və ölçülə bilən qərarı izah etməlidir.\n**Nümunə situasiya:** Tələbə, universitet koordinatoru və HR üçün maraq/səlahiyyət matrisi qur; hər rol üçün 2 müsahibə sualı əlavə et.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Business Analysis / Task-2. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Təsirlənən beş rol müəyyən et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Influence-interest matrisi qur. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Hər rol üçün müsahibə sualları hazırla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Tələbə, universitet koordinatoru və HR üçün maraq/səlahiyyət matrisi qur; hər rol üçün 2 müsahibə sualı əlavə et. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Stakeholder matrix və sual siyahısı. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nTələbə, universitet koordinatoru və HR üçün maraq/səlahiyyət matrisi qur; hər rol üçün 2 müsahibə sualı əlavə et.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Stakeholder matrix və sual siyahısı.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Fakt və fərziyyələri ayır, kimin qərar verəcəyini göstər.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Stakeholder Mapping\nThis practical assignment is designed for beginners. Connect the artifact to a measurable business decision.\n**Example scenario:** Build an interest/influence map for students, university coordinators and HR, with two interview questions per role.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Business Analysis / Task-2. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Identify five impacted roles. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Create an influence-interest matrix. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Draft interview questions for each role. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Build an interest/influence map for students, university coordinators and HR, with two interview questions per role. Document what worked and any limitations.\n7. Complete the main artifact: Stakeholder matrix and interview guide. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nBuild an interest/influence map for students, university coordinators and HR, with two interview questions per role.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Stakeholder matrix and interview guide.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Distinguish facts from assumptions and identify the decision owner.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nStakeholder Mapping: Təsirlənən beş rol müəyyən et. Influence-interest matrisi qur. Hər rol üçün müsahibə sualları hazırla. Pulsuz alətlər: Google Sheets. Nəticə: Stakeholder matrix və sual siyahısı.\n\n[[EN]]\nStakeholder Mapping: Identify five impacted roles. Create an influence-interest matrix. Draft interview questions for each role. Free tools: Google Sheets. Output: Stakeholder matrix and interview guide."},{"slug":"talora-business-analysis-2026","task_number":3,"title":"As-Is Process Analysis","old_instructions":"[[AZ]]\n## Məqsəd\nMövcud sifariş və ya müraciət axınını seç ;  Ən azı altı addımlı BPMN sxemi hazırla ;  Gözləmə və təkrar işi işarələ.\n\n## Addım-addım icra\n1. Mövcud sifariş və ya müraciət axınını seç.\n2. Ən azı altı addımlı BPMN sxemi hazırla.\n3. Gözləmə və təkrar işi işarələ.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nAs-Is BPMN və bottleneck qeydləri. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose a current application or order flow ;  Draw a BPMN diagram with at least six steps ;  Mark delays and rework.\n\n## Step-by-step\n1. Choose a current application or order flow.\n2. Draw a BPMN diagram with at least six steps.\n3. Mark delays and rework.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nAs-is BPMN and bottleneck notes. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nMövcud sifariş və ya müraciət axınını seç ;  Ən azı altı addımlı BPMN sxemi hazırla ;  Gözləmə və təkrar işi işarələ.\n\n[[EN]]\nChoose a current application or order flow ;  Draw a BPMN diagram with at least six steps ;  Mark delays and rework.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: As-Is Process Analysis\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Nəticə biznes problemini və ölçülə bilən qərarı izah etməlidir.\n**Nümunə situasiya:** Müraciət → yoxlama → admin qərarı → bildiriş axınını ən azı 6 addımla çək; gözləməni işarələ.\n\n## Hansı pulsuz alətlər lazımdır?\n- **diagrams.net** — https://app.diagrams.net. Blank diagram aç, fiqurları oxlarla birləşdir, nəticəni PDF/PNG çıxart.\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Business Analysis / Task-3. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Mövcud sifariş və ya müraciət axınını seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Ən azı altı addımlı BPMN sxemi hazırla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Gözləmə və təkrar işi işarələ. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Müraciət → yoxlama → admin qərarı → bildiriş axınını ən azı 6 addımla çək; gözləməni işarələ. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: As-Is BPMN və bottleneck qeydləri. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nMüraciət → yoxlama → admin qərarı → bildiriş axınını ən azı 6 addımla çək; gözləməni işarələ.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** As-Is BPMN və bottleneck qeydləri.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Fakt və fərziyyələri ayır, kimin qərar verəcəyini göstər.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: As-Is Process Analysis\nThis practical assignment is designed for beginners. Connect the artifact to a measurable business decision.\n**Example scenario:** Draw a six-step application-to-decision workflow and clearly mark waiting points.\n\n## Free tools and platforms\n- **diagrams.net** — https://app.diagrams.net. Start a blank diagram, link shapes with arrows, export PDF/PNG.\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Business Analysis / Task-3. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Choose a current application or order flow. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Draw a BPMN diagram with at least six steps. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Mark delays and rework. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Draw a six-step application-to-decision workflow and clearly mark waiting points. Document what worked and any limitations.\n7. Complete the main artifact: As-is BPMN and bottleneck notes. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nDraw a six-step application-to-decision workflow and clearly mark waiting points.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** As-is BPMN and bottleneck notes.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Distinguish facts from assumptions and identify the decision owner.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nAs-Is Process Analysis: Mövcud sifariş və ya müraciət axınını seç. Ən azı altı addımlı BPMN sxemi hazırla. Gözləmə və təkrar işi işarələ. Pulsuz alətlər: diagrams.net, Google Docs. Nəticə: As-Is BPMN və bottleneck qeydləri.\n\n[[EN]]\nAs-Is Process Analysis: Choose a current application or order flow. Draw a BPMN diagram with at least six steps. Mark delays and rework. Free tools: diagrams.net, Google Docs. Output: As-is BPMN and bottleneck notes."},{"slug":"talora-business-analysis-2026","task_number":4,"title":"Requirements Workshop","old_instructions":"[[AZ]]\n## Məqsəd\nBeş funksional və üç qeyri-funksional tələb yaz ;  Hər tələb üçün mənbə və prioritet göstər ;  Qeyri-müəyyən ifadələri konkretləşdir.\n\n## Addım-addım icra\n1. Beş funksional və üç qeyri-funksional tələb yaz.\n2. Hər tələb üçün mənbə və prioritet göstər.\n3. Qeyri-müəyyən ifadələri konkretləşdir.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nRequirements specification. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nWrite five functional and three non-functional requirements ;  Trace every item to a source and priority ;  Replace vague wording.\n\n## Step-by-step\n1. Write five functional and three non-functional requirements.\n2. Trace every item to a source and priority.\n3. Replace vague wording.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nRequirements specification. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nBeş funksional və üç qeyri-funksional tələb yaz ;  Hər tələb üçün mənbə və prioritet göstər ;  Qeyri-müəyyən ifadələri konkretləşdir.\n\n[[EN]]\nWrite five functional and three non-functional requirements ;  Trace every item to a source and priority ;  Replace vague wording.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Requirements Workshop\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Nəticə biznes problemini və ölçülə bilən qərarı izah etməlidir.\n**Nümunə situasiya:** 'Tez cavab' ifadəsini 'qərardan sonra 24 saat ərzində bildiriş' kimi ölçülə bilən tələbə çevir.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Business Analysis / Task-4. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Beş funksional və üç qeyri-funksional tələb yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Hər tələb üçün mənbə və prioritet göstər. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Qeyri-müəyyən ifadələri konkretləşdir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 'Tez cavab' ifadəsini 'qərardan sonra 24 saat ərzində bildiriş' kimi ölçülə bilən tələbə çevir. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Requirements specification. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n'Tez cavab' ifadəsini 'qərardan sonra 24 saat ərzində bildiriş' kimi ölçülə bilən tələbə çevir.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Requirements specification.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Fakt və fərziyyələri ayır, kimin qərar verəcəyini göstər.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Requirements Workshop\nThis practical assignment is designed for beginners. Connect the artifact to a measurable business decision.\n**Example scenario:** Replace 'respond quickly' with a verifiable 'notify within 24 hours of a decision' requirement.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Business Analysis / Task-4. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Write five functional and three non-functional requirements. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Trace every item to a source and priority. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Replace vague wording. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Replace 'respond quickly' with a verifiable 'notify within 24 hours of a decision' requirement. Document what worked and any limitations.\n7. Complete the main artifact: Requirements specification. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nReplace 'respond quickly' with a verifiable 'notify within 24 hours of a decision' requirement.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Requirements specification.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Distinguish facts from assumptions and identify the decision owner.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nRequirements Workshop: Beş funksional və üç qeyri-funksional tələb yaz. Hər tələb üçün mənbə və prioritet göstər. Qeyri-müəyyən ifadələri konkretləşdir. Pulsuz alətlər: Google Docs. Nəticə: Requirements specification.\n\n[[EN]]\nRequirements Workshop: Write five functional and three non-functional requirements. Trace every item to a source and priority. Replace vague wording. Free tools: Google Docs. Output: Requirements specification."},{"slug":"talora-business-analysis-2026","task_number":5,"title":"User Stories and Acceptance Criteria","old_instructions":"[[AZ]]\n## Məqsəd\nİstifadəçi rollarına uyğun altı user story yaz ;  Hər biri üçün Given-When-Then qəbul meyarları əlavə et ;  Təkrarlanan tələbləri birləşdir.\n\n## Addım-addım icra\n1. İstifadəçi rollarına uyğun altı user story yaz.\n2. Hər biri üçün Given-When-Then qəbul meyarları əlavə et.\n3. Təkrarlanan tələbləri birləşdir.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nUser story backlog. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDraft six role-based user stories ;  Add Given-When-Then acceptance tests ;  Remove duplicates.\n\n## Step-by-step\n1. Draft six role-based user stories.\n2. Add Given-When-Then acceptance tests.\n3. Remove duplicates.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nUser-story backlog. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nİstifadəçi rollarına uyğun altı user story yaz ;  Hər biri üçün Given-When-Then qəbul meyarları əlavə et ;  Təkrarlanan tələbləri birləşdir.\n\n[[EN]]\nDraft six role-based user stories ;  Add Given-When-Then acceptance tests ;  Remove duplicates.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: User Stories and Acceptance Criteria\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Nəticə biznes problemini və ölçülə bilən qərarı izah etməlidir.\n**Nümunə situasiya:** 'Tələbə olaraq müraciət statusunu görmək istəyirəm' hekayəsinə Given/When/Then və uğursuz hal əlavə et.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Business Analysis / Task-5. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. İstifadəçi rollarına uyğun altı user story yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Hər biri üçün Given-When-Then qəbul meyarları əlavə et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Təkrarlanan tələbləri birləşdir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 'Tələbə olaraq müraciət statusunu görmək istəyirəm' hekayəsinə Given/When/Then və uğursuz hal əlavə et. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: User story backlog. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n'Tələbə olaraq müraciət statusunu görmək istəyirəm' hekayəsinə Given/When/Then və uğursuz hal əlavə et.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** User story backlog.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Fakt və fərziyyələri ayır, kimin qərar verəcəyini göstər.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: User Stories and Acceptance Criteria\nThis practical assignment is designed for beginners. Connect the artifact to a measurable business decision.\n**Example scenario:** Write Given/When/Then criteria for a student checking application status, including a failure case.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Business Analysis / Task-5. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Draft six role-based user stories. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Add Given-When-Then acceptance tests. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Remove duplicates. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Write Given/When/Then criteria for a student checking application status, including a failure case. Document what worked and any limitations.\n7. Complete the main artifact: User-story backlog. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nWrite Given/When/Then criteria for a student checking application status, including a failure case.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** User-story backlog.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Distinguish facts from assumptions and identify the decision owner.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nUser Stories and Acceptance Criteria: İstifadəçi rollarına uyğun altı user story yaz. Hər biri üçün Given-When-Then qəbul meyarları əlavə et. Təkrarlanan tələbləri birləşdir. Pulsuz alətlər: Google Docs, Google Sheets. Nəticə: User story backlog.\n\n[[EN]]\nUser Stories and Acceptance Criteria: Draft six role-based user stories. Add Given-When-Then acceptance tests. Remove duplicates. Free tools: Google Docs, Google Sheets. Output: User-story backlog."},{"slug":"talora-business-analysis-2026","task_number":6,"title":"To-Be Process Design","old_instructions":"[[AZ]]\n## Məqsəd\nMövcud sxemdə iki təkmilləşdirmə seç ;  Hədəf BPMN axınını modelləşdir ;  Dəyişikliklərin risklərini izah et.\n\n## Addım-addım icra\n1. Mövcud sxemdə iki təkmilləşdirmə seç.\n2. Hədəf BPMN axınını modelləşdir.\n3. Dəyişikliklərin risklərini izah et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nTo-Be BPMN və fərqlər cədvəli. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose two improvements ;  Model the target BPMN process ;  Explain trade-offs and risks.\n\n## Step-by-step\n1. Choose two improvements.\n2. Model the target BPMN process.\n3. Explain trade-offs and risks.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nTo-be BPMN and gap analysis. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nMövcud sxemdə iki təkmilləşdirmə seç ;  Hədəf BPMN axınını modelləşdir ;  Dəyişikliklərin risklərini izah et.\n\n[[EN]]\nChoose two improvements ;  Model the target BPMN process ;  Explain trade-offs and risks.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: To-Be Process Design\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Nəticə biznes problemini və ölçülə bilən qərarı izah etməlidir.\n**Nümunə situasiya:** Köhnə 6 addımlı prosesi 4 addımla müqayisə et, avtomatlaşan yoxlamanı və məsul şəxsi qeyd et.\n\n## Hansı pulsuz alətlər lazımdır?\n- **diagrams.net** — https://app.diagrams.net. Blank diagram aç, fiqurları oxlarla birləşdir, nəticəni PDF/PNG çıxart.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Business Analysis / Task-6. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Mövcud sxemdə iki təkmilləşdirmə seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Hədəf BPMN axınını modelləşdir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Dəyişikliklərin risklərini izah et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Köhnə 6 addımlı prosesi 4 addımla müqayisə et, avtomatlaşan yoxlamanı və məsul şəxsi qeyd et. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: To-Be BPMN və fərqlər cədvəli. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nKöhnə 6 addımlı prosesi 4 addımla müqayisə et, avtomatlaşan yoxlamanı və məsul şəxsi qeyd et.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** To-Be BPMN və fərqlər cədvəli.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Fakt və fərziyyələri ayır, kimin qərar verəcəyini göstər.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: To-Be Process Design\nThis practical assignment is designed for beginners. Connect the artifact to a measurable business decision.\n**Example scenario:** Compare a six-step existing process with a four-step target and specify automation and ownership.\n\n## Free tools and platforms\n- **diagrams.net** — https://app.diagrams.net. Start a blank diagram, link shapes with arrows, export PDF/PNG.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Business Analysis / Task-6. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Choose two improvements. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Model the target BPMN process. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Explain trade-offs and risks. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Compare a six-step existing process with a four-step target and specify automation and ownership. Document what worked and any limitations.\n7. Complete the main artifact: To-be BPMN and gap analysis. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCompare a six-step existing process with a four-step target and specify automation and ownership.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** To-be BPMN and gap analysis.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Distinguish facts from assumptions and identify the decision owner.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nTo-Be Process Design: Mövcud sxemdə iki təkmilləşdirmə seç. Hədəf BPMN axınını modelləşdir. Dəyişikliklərin risklərini izah et. Pulsuz alətlər: diagrams.net. Nəticə: To-Be BPMN və fərqlər cədvəli.\n\n[[EN]]\nTo-Be Process Design: Choose two improvements. Model the target BPMN process. Explain trade-offs and risks. Free tools: diagrams.net. Output: To-be BPMN and gap analysis."},{"slug":"talora-business-analysis-2026","task_number":7,"title":"Prioritization and Scope","old_instructions":"[[AZ]]\n## Məqsəd\nMoSCoW ilə tələbləri qruplaşdır ;  MVP sərhədlərini müəyyən et ;  Scope-dan çıxarılanları əsaslandır.\n\n## Addım-addım icra\n1. MoSCoW ilə tələbləri qruplaşdır.\n2. MVP sərhədlərini müəyyən et.\n3. Scope-dan çıxarılanları əsaslandır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nPrioritetləndirmə matrisi. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nGroup requirements with MoSCoW ;  Define an MVP boundary ;  Justify exclusions.\n\n## Step-by-step\n1. Group requirements with MoSCoW.\n2. Define an MVP boundary.\n3. Justify exclusions.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nPriority matrix. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nMoSCoW ilə tələbləri qruplaşdır ;  MVP sərhədlərini müəyyən et ;  Scope-dan çıxarılanları əsaslandır.\n\n[[EN]]\nGroup requirements with MoSCoW ;  Define an MVP boundary ;  Justify exclusions.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Prioritization and Scope\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Nəticə biznes problemini və ölçülə bilən qərarı izah etməlidir.\n**Nümunə situasiya:** MVP üçün status izləməni Must, avtomatik tövsiyələri Could kimi prioritetləşdir; səbəb yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Business Analysis / Task-7. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. MoSCoW ilə tələbləri qruplaşdır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. MVP sərhədlərini müəyyən et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Scope-dan çıxarılanları əsaslandır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: MVP üçün status izləməni Must, avtomatik tövsiyələri Could kimi prioritetləşdir; səbəb yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Prioritetləndirmə matrisi. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nMVP üçün status izləməni Must, avtomatik tövsiyələri Could kimi prioritetləşdir; səbəb yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Prioritetləndirmə matrisi.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Fakt və fərziyyələri ayır, kimin qərar verəcəyini göstər.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Prioritization and Scope\nThis practical assignment is designed for beginners. Connect the artifact to a measurable business decision.\n**Example scenario:** Prioritize application status tracking as Must and automated suggestions as Could, with reasons.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Business Analysis / Task-7. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Group requirements with MoSCoW. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Define an MVP boundary. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Justify exclusions. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Prioritize application status tracking as Must and automated suggestions as Could, with reasons. Document what worked and any limitations.\n7. Complete the main artifact: Priority matrix. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nPrioritize application status tracking as Must and automated suggestions as Could, with reasons.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Priority matrix.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Distinguish facts from assumptions and identify the decision owner.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nPrioritization and Scope: MoSCoW ilə tələbləri qruplaşdır. MVP sərhədlərini müəyyən et. Scope-dan çıxarılanları əsaslandır. Pulsuz alətlər: Google Sheets. Nəticə: Prioritetləndirmə matrisi.\n\n[[EN]]\nPrioritization and Scope: Group requirements with MoSCoW. Define an MVP boundary. Justify exclusions. Free tools: Google Sheets. Output: Priority matrix."},{"slug":"talora-business-analysis-2026","task_number":8,"title":"KPI and Measurement Plan","old_instructions":"[[AZ]]\n## Məqsəd\nÜç ölçülə bilən KPI seç ;  Hər KPI üçün mənbə və hesablanma qaydası yaz ;  Başlanğıc və hədəf dəyərləri nümunəvi göstər.\n\n## Addım-addım icra\n1. Üç ölçülə bilən KPI seç.\n2. Hər KPI üçün mənbə və hesablanma qaydası yaz.\n3. Başlanğıc və hədəf dəyərləri nümunəvi göstər.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nKPI dictionary. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nSelect three measurable KPIs ;  Define sources and formulas ;  Illustrate baseline and target with synthetic data.\n\n## Step-by-step\n1. Select three measurable KPIs.\n2. Define sources and formulas.\n3. Illustrate baseline and target with synthetic data.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nKPI dictionary. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nÜç ölçülə bilən KPI seç ;  Hər KPI üçün mənbə və hesablanma qaydası yaz ;  Başlanğıc və hədəf dəyərləri nümunəvi göstər.\n\n[[EN]]\nSelect three measurable KPIs ;  Define sources and formulas ;  Illustrate baseline and target with synthetic data.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: KPI and Measurement Plan\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Nəticə biznes problemini və ölçülə bilən qərarı izah etməlidir.\n**Nümunə situasiya:** Orta cavab vaxtı = qərar tarixi − müraciət tarixi; 5 sintetik müraciətlə hesablama apar.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Business Analysis / Task-8. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Üç ölçülə bilən KPI seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Hər KPI üçün mənbə və hesablanma qaydası yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Başlanğıc və hədəf dəyərləri nümunəvi göstər. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Orta cavab vaxtı = qərar tarixi − müraciət tarixi; 5 sintetik müraciətlə hesablama apar. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: KPI dictionary. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nOrta cavab vaxtı = qərar tarixi − müraciət tarixi; 5 sintetik müraciətlə hesablama apar.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** KPI dictionary.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Fakt və fərziyyələri ayır, kimin qərar verəcəyini göstər.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: KPI and Measurement Plan\nThis practical assignment is designed for beginners. Connect the artifact to a measurable business decision.\n**Example scenario:** Calculate average response time from five fictional application and decision timestamps.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Business Analysis / Task-8. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Select three measurable KPIs. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Define sources and formulas. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Illustrate baseline and target with synthetic data. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Calculate average response time from five fictional application and decision timestamps. Document what worked and any limitations.\n7. Complete the main artifact: KPI dictionary. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCalculate average response time from five fictional application and decision timestamps.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** KPI dictionary.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Distinguish facts from assumptions and identify the decision owner.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nKPI and Measurement Plan: Üç ölçülə bilən KPI seç. Hər KPI üçün mənbə və hesablanma qaydası yaz. Başlanğıc və hədəf dəyərləri nümunəvi göstər. Pulsuz alətlər: Google Sheets. Nəticə: KPI dictionary.\n\n[[EN]]\nKPI and Measurement Plan: Select three measurable KPIs. Define sources and formulas. Illustrate baseline and target with synthetic data. Free tools: Google Sheets. Output: KPI dictionary."},{"slug":"talora-business-analysis-2026","task_number":9,"title":"UAT Test Scenarios","old_instructions":"[[AZ]]\n## Məqsəd\nKritik üç istifadəçi ssenarisini seç ;  Altı UAT test case hazırla ;  Gözlənilən nəticə və bug qeydini nümunələndir.\n\n## Addım-addım icra\n1. Kritik üç istifadəçi ssenarisini seç.\n2. Altı UAT test case hazırla.\n3. Gözlənilən nəticə və bug qeydini nümunələndir.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nUAT test matrix. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose three critical user journeys ;  Write six UAT cases ;  Record expected outcomes and sample defects.\n\n## Step-by-step\n1. Choose three critical user journeys.\n2. Write six UAT cases.\n3. Record expected outcomes and sample defects.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nUAT test matrix. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nKritik üç istifadəçi ssenarisini seç ;  Altı UAT test case hazırla ;  Gözlənilən nəticə və bug qeydini nümunələndir.\n\n[[EN]]\nChoose three critical user journeys ;  Write six UAT cases ;  Record expected outcomes and sample defects.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: UAT Test Scenarios\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Nəticə biznes problemini və ölçülə bilən qərarı izah etməlidir.\n**Nümunə situasiya:** Qəbul edilmiş və rədd edilmiş müraciət üçün 6 test yaz: giriş, addım, gözlənilən nəticə.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Business Analysis / Task-9. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Kritik üç istifadəçi ssenarisini seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Altı UAT test case hazırla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Gözlənilən nəticə və bug qeydini nümunələndir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Qəbul edilmiş və rədd edilmiş müraciət üçün 6 test yaz: giriş, addım, gözlənilən nəticə. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: UAT test matrix. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nQəbul edilmiş və rədd edilmiş müraciət üçün 6 test yaz: giriş, addım, gözlənilən nəticə.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** UAT test matrix.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Fakt və fərziyyələri ayır, kimin qərar verəcəyini göstər.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: UAT Test Scenarios\nThis practical assignment is designed for beginners. Connect the artifact to a measurable business decision.\n**Example scenario:** Write six acceptance tests for accepted/rejected applications with inputs, steps and expected results.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Business Analysis / Task-9. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Choose three critical user journeys. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Write six UAT cases. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Record expected outcomes and sample defects. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Write six acceptance tests for accepted/rejected applications with inputs, steps and expected results. Document what worked and any limitations.\n7. Complete the main artifact: UAT test matrix. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nWrite six acceptance tests for accepted/rejected applications with inputs, steps and expected results.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** UAT test matrix.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Distinguish facts from assumptions and identify the decision owner.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nUAT Test Scenarios: Kritik üç istifadəçi ssenarisini seç. Altı UAT test case hazırla. Gözlənilən nəticə və bug qeydini nümunələndir. Pulsuz alətlər: Google Sheets. Nəticə: UAT test matrix.\n\n[[EN]]\nUAT Test Scenarios: Choose three critical user journeys. Write six UAT cases. Record expected outcomes and sample defects. Free tools: Google Sheets. Output: UAT test matrix."},{"slug":"talora-business-analysis-2026","task_number":10,"title":"Business Analysis Handoff","old_instructions":"[[AZ]]\n## Məqsəd\nƏvvəlki artefaktları birləşdir ;  Dəyişiklik təklifini beş dəqiqəlik təqdimatla izah et ;  Açıq sual və riskləri qeyd et.\n\n## Addım-addım icra\n1. Əvvəlki artefaktları birləşdir.\n2. Dəyişiklik təklifini beş dəqiqəlik təqdimatla izah et.\n3. Açıq sual və riskləri qeyd et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nFinal BA portfolio və təqdimat. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCombine previous artifacts ;  Present recommendations in five minutes ;  Document open questions and risks.\n\n## Step-by-step\n1. Combine previous artifacts.\n2. Present recommendations in five minutes.\n3. Document open questions and risks.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nFinal BA portfolio and presentation. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nƏvvəlki artefaktları birləşdir ;  Dəyişiklik təklifini beş dəqiqəlik təqdimatla izah et ;  Açıq sual və riskləri qeyd et.\n\n[[EN]]\nCombine previous artifacts ;  Present recommendations in five minutes ;  Document open questions and risks.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Business Analysis Handoff\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Nəticə biznes problemini və ölçülə bilən qərarı izah etməlidir.\n**Nümunə situasiya:** Problem, proses sxemləri, backlog və KPI-ları 5–6 slayda yığ, üç tövsiyəni əsaslandır.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Slides** — https://slides.google.com. Bir slaydda bir əsas fikir yerləşdir, sonunda PDF eksport et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Business Analysis / Task-10. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Əvvəlki artefaktları birləşdir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Dəyişiklik təklifini beş dəqiqəlik təqdimatla izah et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Açıq sual və riskləri qeyd et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Problem, proses sxemləri, backlog və KPI-ları 5–6 slayda yığ, üç tövsiyəni əsaslandır. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Final BA portfolio və təqdimat. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nProblem, proses sxemləri, backlog və KPI-ları 5–6 slayda yığ, üç tövsiyəni əsaslandır.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Final BA portfolio və təqdimat.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Fakt və fərziyyələri ayır, kimin qərar verəcəyini göstər.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Business Analysis Handoff\nThis practical assignment is designed for beginners. Connect the artifact to a measurable business decision.\n**Example scenario:** Package the problem, workflows, backlog and KPIs in five or six slides with three recommendations.\n\n## Free tools and platforms\n- **Google Slides** — https://slides.google.com. Use one idea per slide, then export the presentation as PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Business Analysis / Task-10. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Combine previous artifacts. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Present recommendations in five minutes. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Document open questions and risks. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Package the problem, workflows, backlog and KPIs in five or six slides with three recommendations. Document what worked and any limitations.\n7. Complete the main artifact: Final BA portfolio and presentation. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nPackage the problem, workflows, backlog and KPIs in five or six slides with three recommendations.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Final BA portfolio and presentation.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Distinguish facts from assumptions and identify the decision owner.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nBusiness Analysis Handoff: Əvvəlki artefaktları birləşdir. Dəyişiklik təklifini beş dəqiqəlik təqdimatla izah et. Açıq sual və riskləri qeyd et. Pulsuz alətlər: Google Slides. Nəticə: Final BA portfolio və təqdimat.\n\n[[EN]]\nBusiness Analysis Handoff: Combine previous artifacts. Present recommendations in five minutes. Document open questions and risks. Free tools: Google Slides. Output: Final BA portfolio and presentation."}]$guide_payload$::jsonb);
DO $preflight$
DECLARE matched integer;
BEGIN
 SELECT COUNT(*) INTO matched FROM curriculum_revised c
 CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id
   AND t.task_number=(e.item->>'task_number')::integer
   AND t.title=e.item->>'title'
 WHERE t.instructions=e.item->>'old_instructions'
 AND t.description=e.item->>'old_description'
 AND i.slug='talora-business-analysis-2026';
 IF (SELECT jsonb_array_length(payload) FROM curriculum_revised)<>10 OR matched<>10 THEN
  RAISE EXCEPTION 'Content version mismatch for talora-business-analysis-2026; matched %',matched;
 END IF;
END; $preflight$;
UPDATE public.internship_tasks t
SET instructions=e.item->>'new_instructions', description=e.item->>'new_description'
FROM curriculum_revised c
CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
JOIN public.internships i ON i.slug=e.item->>'slug'
WHERE i.slug='talora-business-analysis-2026'
AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
AND t.title=e.item->>'title';
DO $verify$
DECLARE matched integer;
BEGIN
 SELECT COUNT(*) INTO matched FROM curriculum_revised c
 CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required AND i.slug='talora-business-analysis-2026';
 IF matched<>10 THEN RAISE EXCEPTION 'Verification failed after update for talora-business-analysis-2026: %',matched; END IF;
END; $verify$;
COMMIT;